mapper.select:
SELECT id, admin_id, admin_username, action, target_type, target_id, detail, ip, create_time
FROM admin_operation_log


        AND action = #{action}


        AND admin_username LIKE CONCAT('%', #{adminUsername}, '%')


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC, id DESC
